-- 163_replace_decision_229_2025_health_care_programs_management_companies_rules_polluted_with_watermark_page_headers_and_chapter_headings_with_preamble_3_issuance_articles_and_24_rules.sql
--
-- إعادة رفع قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم (229) لسنة 2025 بشأن القواعد والمعايير المنظمة لمزاولة نشاط إدارة برامج الرعاية الصحية،
-- المنشور بالوقائع المصرية، العدد 254 تابع (أ)، فى 12 نوفمبر 2025 (الصفحات 2 إلى 26): قرار من ثلاث مواد إصدار مرفق به "القواعد والمعايير المنظمة لمزاولة نشاط إدارة برامج الرعاية الصحية" فى 24 مادة وأربعة فصول.
--
-- ===== الحالة السابقة (مراجعة الـ153 وثيقة، أولوية P2 - المجموعة د) =====
-- مخزَّن بالهجرات 004 و005 و006 (24 صفاً، 33866 حرفاً؛ البذور الثلاثة تحمل الكتلة نفسها فيبقى ما أدخلته 004 لأن الإدراج ON CONFLICT DO NOTHING) مأخوذ من طبقة النص فى PDF دون تنظيف:
-- مواد القواعد 1-24 فقط، بلا ديباجة ولا مواد الإصدار الثلاث (نطاق التطبيق، توفيق الأوضاع، النشر والتوقيع) ولا حقل title ولا hierarchical_location، فلا يعرف القارئ أن المواد قواعد مرفقة بقرار، ولا يجد أن مهلة توفيق الأوضاع تنتهى فى 2026/7/10 ولا تاريخ سريان القرار.
-- وقورن المخزَّن بالنص المنقول من المصدر مادة مادة بعد توحيد الهمزات والياء والتاء المربوطة وحذف التشكيل وعلامات الترقيم والمسافات، فلم يبق فرق فى ألفاظ القواعد نفسها إلا ما يأتى، وكله تلوث من الاستخراج:
-- (1) شظايا نص العلامة المائية القطرية للوقائع ("لك" و"تروني" و"ة ال يع" و"تد بها" و"عند ا" و"ل" و"تداول" و"صورة إ") فى الصفوف الـ24 كلها تتخلل الجمل وتقطعها؛
-- (2) ترويسة صفحات الوقائع ("الوقائع المصریة - العدد 254 تابع )أ( فى 12 نوفمبر سنة 2025" ورقم الصفحة) داخل 18 صفاً؛
-- (3) عنوان كل مادة سطر أول داخل المتن بدل حقل عنوان مستقل، وعناوين الفصول الثانى والثالث والرابع ملتصقة بآخر المواد 6 و8 و12 ("الفصل الثانى / مجلس إدارة والهيكل التنظيمى لشركات إدارة برامج الرعاية الصحية" وما شابهها) بدل أن تكون hierarchical_location؛
-- (4) قائمة أرقام البنود فى المادة 7 ("البنود 1 و2 و3 و5 و8 من هذه المادة") مخزَّنة بترتيب وأقواس مختلّين، والإحالة "من 1 إلى 8" بالمادة 8 بأقواس معكوسة، والنسبة "(25%)" بالمادة 6 والإحالة "(15)" بالمادة 23 ومرجع البند "(أ)" بالمادتين 16 و18 مخزَّنة بأقواسها معكوسة أو مفصولة؛
-- (5) حروف خاصة من الخط (U+E821 وU+E823، 37 حرفاً فى 17 صفاً) محل الضمة والتنوين فى كلمات مثل "سنويًا" و"وفقًا" و"تعزيزًا"، وتنوين مفصول عن حرفه ("مرفق ًا" و"طرف ًا")، وياء فارسية ("مدى")، وأرقام هندية وفارسية (450 رقماً فى 22 صفاً)، وأرقام البنود ملتصقة بالكلمة التالية؛
-- (6) فواصل أسطر الصفحة (707 فاصل CRLF) داخل الجمل فى الصفوف الـ24 كلها، تبدأ معظم أسطرها بمسافة فتنقطع الفقرات والبنود.
-- فلا يصلح النص المخزَّن للاستشهاد الرسمى، ولا لإدخاله إلى سياق نموذج اللغة: شظايا العلامة المائية والترويسة وعناوين الفصول تقطع الجمل، والمواد بلا نطاق التطبيق ولا تاريخ سريان.
--
-- ===== المصدر والمنهجية =====
-- PDF الوقائع المصرية (25 صفحة، 512.5 كيلوبايت) قدّمه صاحب المشروع. فى الملف طبقة نصية بخط مضمَّن، تتخللها كتل العلامة المائية القطرية بخط مستقل (Ahab)، فنُزعت من الملف عمليات رسم نص ذلك الخط قبل الاستخراج.
-- استُخرج النص بترتيبه المنطقى وحُوِّلت الصيغ الشكلية للحروف إلى حروف عادية (NFKC)، وأعيد تركيب الفقرات والبنود من أسطر الصفحة بإحداثيات الأسطر (بداية الفقرة أو البند سطر مُزاح عن الهامش الأيمن بمقدار ثابت فى كل صفحات الملف)،
-- وصُحِّح ما يفسده تخزين الأحرف بترتيب بصرى: معكوسات الأقواس والنسبة المئوية وقوائم أرقام البنود (قُرئت على صور الصفحات 9 و10 و12 من الملف)، وإعادة ضم التنوين المنفصل ("وفقًا" بدل "وفًقا" بمادة الإصدار الثانية)، وموضع الفاصلة بعد التاريخ فى مادة الإصدار الثانية
-- ("2026/7/10 ، ويجوز مد"). وكُتبت الفاصلة المائلة بين "العضو المنتدب" و"الرئيس التنفيذى" بمسافة قبلها وبعدها كما تظهر فى صورة الصفحة ("المنتدب / الرئيس التنفيذي")،
-- ثم قوبل النص المُدخَل بمخرجات OCR مستقلة (tesseract ara) على صور الصفحات الخمس والعشرين بعد إزالة خلفية العلامة المائية: لم يبق فرق فى ألفاظ غير ضجيج التعرف على الحروف والأرقام الهندية والعناوين ولا فرق حقيقى فى كلمة واحدة،
-- وقُرئت بصرياً المواضع المشتبهة (ترويسة العدد وتاريخه، والتاريخ والفاصلة بمادة الإصدار الثانية، والتوقيع "د/ محمد فريد صالح"، وقوائم أرقام البنود بالمادتين 7 و8، والنسبة المئوية بالمادة 6، والفاصلة المائلة). أُبقيت كتابة الوقائع كما طُبعت ("فى" و"في" معاً، "الأعضاء مجلس الإدارة" بالمادة 24،
-- "البيانات الأرقام" بالمادة 19، "المراجعة داخلية" بالمادة 8، "موافقة الكتابية" بالمادة 9، "أراء" بالمادة 18، ووضع النقطة الأخيرة كما طُبعت، ملاصقة للكلمة أو بمسافة قبلها)؛ الأرقام لاتينية والتنوين فى موضعه كما طُبع وأُسقطت الضمة وغيرها من علامات التشكيل الصغيرة ومعها التطويل (فصار "(هـ)" "(ه)")؛
-- ضُبطت المسافات حول الفاصلة والنقطتين والفاصلة المنقوطة (" ، " و" : " و" ؛ ") وحول علامة الجمع، وأُضيفت مسافة بين الرقم أو القوس والكلمة الملتصقة به؛ وأُبقيت النقطة الأخيرة وغيابها كما طُبعا. النسبة المئوية بلا مسافات داخل الأقواس "(25%)".
-- حُذفت الترويسة وأرقام الصفحات وشعار العلامة المائية، وسطر "مجلس إدارة الهيئة العامة للرقابة المالية" (جهة الإصدار)، وعنوان القرار يوضع فى hierarchical_location للديباجة. التوقيع داخل مادة الإصدار الثالثة.
--
-- ===== الهيكل =====
-- 28 صفاً، 28 نسخة (version_no = 1): ديباجة (article_no = 0) بالاطلاعات السبعة (القانون 10 لسنة 2009، وقانون التأمين الموحد 155 لسنة 2024، والقرارات 244 لسنة 2023 و161 لسنة 2024 و177 لسنة 2024 و196 لسنة 2024 و90 لسنة 2025)
-- وموافقة مجلس الإدارة بجلسته المنعقدة بتاريخ 2025/9/24؛ ثم مواد الإصدار الثلاث (الأولى نطاق التطبيق والترخيص، الثانية توفيق الأوضاع، الثالثة النشر والتوقيع، وكلها بلا عنوان كما فى الأصل) بمفاتيح (1 و2 و3 مع article_suffix_order = -1)
-- وهو اصطلاح المنصة نفسه لمواد الإصدار التى تشارك أرقام مواد القواعد المرفقة (راجع الهجرة 022 لقرارات 145/2021 و135/1993)، ثم مواد القواعد 1 إلى 24 بأرقامها الأصلية (article_suffix_order = 0) وعناوينها (حقل title، "المادة 1 - المتطلبات الواجب توافرها لتأسيس وترخيص شركات إدارة برامج الرعاية الصحية" ...)،
-- وفى hierarchical_location "القواعد والمعايير المنظمة لمزاولة نشاط إدارة برامج الرعاية الصحية" مع الفصل وعنوانه كما فى الأصل: الفصل الأول (تأسيس وترخيص والقيد بسجل شركات إدارة برامج الرعاية الصحية، المواد 1-6)، الفصل الثانى (مجلس إدارة والهيكل التنظيمى لشركات إدارة برامج الرعاية الصحية، المادتان 7-8)،
-- الفصل الثالث (الالتزامات والمحظورات على شركات إدارة برامج الرعاية الصحية، 9-12)، الفصل الرابع (حوكمة شركات إدارة برامج الرعاية الصحية، 13-24).
-- فمفاتيح مواد القواعد (1..24، 0) هى نفسها المخزَّنة فلا تعيد بذور 004/005/006 إدراج المواد القديمة (إدراج laws فيها ON CONFLICT DO NOTHING، وإدراج المواد مبنى على RETURNING فلا يعمل مع قانون موجود)، ولا تخلط مواد الإصدار برقم مادة القواعد: المسار المباشر برقم المادة (article_suffix_order = 0) يعيد مادة القواعد.
--
-- ===== التاريخ =====
-- effective_from = 2025-11-13: مادة الإصدار الثالثة تعمل بالقرار "من اليوم التالي لتاريخ نشره بالوقائع المصرية"، ونشره بالعدد 254 تابع (أ) بتاريخ 2025/11/12 (ثابت بترويسة كل صفحة). كان القديم تاريخ تشغيل البذر لا تاريخ سريان.
-- (نص مادة الإصدار الثانية يمنح الشركات القائمة مهلة لتوفيق أوضاعها حتى 2026/7/10 "ويجوز مد هذه المهلة وفقًا لما يقدره مجلس إدارة الهيئة"؛ هذه الهجرة تنقل نص القرار كما نُشر ولا تعدّله، وأى مد لاحق للمهلة يُعالج بنسخة مستقلة إن ثبت بقرار منشور.)
--
-- ===== قابلية إعادة التشغيل =====
-- الحذف مشروط بألا تكون الحالة نظيفة (28 صفاً بديباجة سليمة والمادة 24 موجودة)؛ والإدراج ON CONFLICT DO NOTHING. تحقق الختام محصور فى هذا القرار ويفشل عند أى انحراف (عدد، علامة مائية، أو ترويسة، أو بقايا تلف،
-- أو محتوى المواد، أو إجمالى الطول 31597 حرفاً).
--
-- ملاحظة تشغيلية: المواد الجديدة بلا embedding؛ يلزم scripts/backfill-embeddings.js بعد النشر.
BEGIN;
DO $fix163$
DECLARE
  v_law_id uuid;
  v_n int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[163] القرار 229/2025 غير موجود فى laws — تخطّى';
    RETURN;
  END IF;
  IF (SELECT count(*) FROM articles WHERE law_id = v_law_id) = 28
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND title = 'ديباجة القرار' AND body LIKE 'بعد الاطلاع%')
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 24 AND article_suffix_order = 0) THEN
    RAISE NOTICE '[163] القرار 229/2025 نظيف بالفعل — تخطّى الحذف';
  ELSE
    SELECT count(*) INTO v_n FROM articles WHERE law_id = v_law_id;
    DELETE FROM articles WHERE law_id = v_law_id;
    RAISE NOTICE '[163] أُزيلت % مادة من القرار 229/2025 (نص مخزَّن ملوَّث بعلامة مائية وبقايا استخراج، وبلا ديباجة ولا مواد الإصدار الثلاث)', v_n;
  END IF;
END
$fix163$;

WITH ins0_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 0, 0, $h0$قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم 229 لسنة 2025 (منشور بالوقائع المصرية العدد 254 تابع (أ) فى 2025/11/12) بشأن القواعد والمعايير المنظمة لمزاولة نشاط إدارة برامج الرعاية الصحية$h0$, $t0_0$ديباجة القرار$t0_0$, $b0_0$بعد الاطلاع على القانون رقم 10 لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية ؛
وعلى قانون التأمين الموحد الصادر بالقانون رقم 155 لسنة 2024 ؛
وعلى قرار مجلس إدارة الهيئة رقم 244 لسنة 2023 بشأن إعادة تنظيم ضوابط القيد واستمرار القيد والشطب فى سجل مراقبى الحسابات لدى الهيئة ؛
وعلى قرار مجلس إدارة الهيئة رقم 161 لسنة 2024 بشأن الضوابط الرقابية في مجال مكافحة غسل الأموال وتمويل الإرهاب للجهات العاملة فى مجال الأنشطة المالية غير المصرفية ؛
وعلى قرار مجلس إدارة الهيئة رقم 177 لسنة 2024 بشأن ضوابط منح الترخيص واستمراره للشركات العاملة في الأنشطة المالية غير المصرفية ؛
وعلى قرار مجلس إدارة الهيئة رقم 196 لسنة 2024 بشأن تحديد الحد الأدنى لرؤوس أموال الشركات العاملة في قطاع التأمين ؛
وعلى قرار مجلس إدارة الهيئة رقم 90 لسنة 2025 بشأن شروط وإجراءات الحصول على الترخيص المؤقت لشركات التأمين الطبي المتخصصة وشركات إدارة برامج الرعاية الصحية ؛
وبعد موافقة مجلس إدارة الهيئة بجلسته المنعقدة بتاريخ 2025/9/24 ؛$b0_0$
  FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-11-13', 'active' FROM ins0_0;

WITH ins1_m1 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 1, -1, NULL, $t1_m1$المادة الأولى$t1_m1$, $b1_m1$تسري القواعد والمعايير المرفقة بهذا القرار في شأن التأسيس والترخيص وتنظيم مزاولة نشاط شركات إدارة برامج الرعاية الصحية ، وتكون الهيئة دون غيرها هي المختصة بالتأسيس والترخيص والإشراف والرقابة على تلك الشركات.
ولا يجوز لأي شركة مزاولة نشاط إدارة برامج الرعاية الصحية إلا بعد الحصول على ترخيص بذلك من الهيئة والقيد لديها في السجل المعد لذلك .
ويكون استمرار توافر المتطلبات الواردة بهذا القرار شرطًا لاستمرار الترخيص بمزاولة النشاط .$b1_m1$
  FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-11-13', 'active' FROM ins1_m1;

WITH ins2_m1 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 2, -1, NULL, $t2_m1$المادة الثانية$t2_m1$, $b2_m1$على شركات إدارة برامج الرعاية الصحية القائمة قبل العمل بأحكام قانون التأمين الموحد التقدم للهيئة للحصول على ترخيص مؤقت وفقًا لأحكام قرار مجلس إدارة الهيئة رقم 90 لسنة 2025 المشار إليه على أن تلتزم بتوفيق أوضاعها وفقًا للقواعد والمعايير المرفقة بهذا القرار خلال مدة أقصاها 2026/7/10 ، ويجوز مد هذه المهلة وفقًا لما يقدره مجلس إدارة الهيئة .
ويعد الترخيص المؤقت لاغيًا في حال عدم قيام الشركة بتوفيق أوضاعها خلال المدة المشار إليها ، كما يلغى قرار مجلس إدارة الهيئة رقم 90 لسنة 2025 المشار إليه فيما يخص الشركات المخاطبة بأحكام هذا القرار في نهاية مدة توفيق الأوضاع المذكورة .$b2_m1$
  FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-11-13', 'active' FROM ins2_m1;

WITH ins3_m1 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 3, -1, NULL, $t3_m1$المادة الثالثة$t3_m1$, $b3_m1$ينشر هذا القرار في الوقائع المصرية وعلى الموقع الإلكتروني للهيئة ، ويعمل به من اليوم التالي لتاريخ نشره بالوقائع المصرية .
رئيس مجلس إدارة
الهيئة العامة للرقابة المالية
د/ محمد فريد صالح$b3_m1$
  FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
