SELECT id, 1, body, '2025-11-13', 'active' FROM ins3_m1;

WITH ins1_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 1, 0, $h1$القواعد والمعايير المنظمة لمزاولة نشاط إدارة برامج الرعاية الصحية - الفصل الأول - تأسيس وترخيص والقيد بسجل شركات إدارة برامج الرعاية الصحية$h1$, $t1_0$المادة 1 - المتطلبات الواجب توافرها لتأسيس وترخيص شركات إدارة برامج الرعاية الصحية$t1_0$, $b1_0$يشترط لتأسيس وترخيص شركات إدارة برامج الرعاية الصحية استيفاء الشروط الآتية :
1- أن تتخذ شكل شركة مساهمة مصرية يقتصر غرضها على مزاولة نشاط إدارة برامج الرعاية الصحية .
2- ألا يقل رأس مالها المصدر والمدفوع عند التأسيس عن الحد الأدنى الوارد بقرار مجلس إدارة الهيئة رقم 196 لسنة 2024 المشار إليه .
3- أن يتفق هيكل مساهمي الشركة والغرض من إنشائها ونسب تملك مساهميها مع أحكام قرارات مجلس إدارة الهيئة الصادرة بشأن ضوابط منح الترخيص واستمراره للشركات العاملة في الأنشطة المالية غير المصرفية وضوابط موافقة الهيئة على التملك والسيطرة والاندماج للشركات المشار إليها .
4- ألا يكون من بين مساهميها أو القائمين على إدارتها أي من العاملين بشركات التأمين أو إعادة التأمين.
5- الإفصاح للهيئة عن أقارب المساهمين حتى الدرجة الثانية حال قيامهم بتأسيس أو تملك أو إدارة أي من شركات التأمين أو إعادة التأمين .
6- أن يتوافر فيمن يؤسس الشركة ما يلي :
أولاً - بالنسبة للأشخاص الطبيعيين
(أ) ألا يكون قد سبق الحكم عليه خلال السنوات الخمس السابقة على تاريخ تقديم طلب التأسيس ، بعقوبة جناية أو بعقوبة جنحة في جريمة ماسة بالشرف أو الأمانة أو بعقوبة سالبة للحرية في إحدى الجرائم المنصوص عليها في قوانين الشركات أو التجارة أو القوانين المنظمة للأنشطة المالية غير المصرفية أو حكم بإشهار إفلاسه ما لم يكن قد رد إليه اعتباره .
(ب) ألا يقوم به عارض من عوارض الأهلية .
(ج) أن يتوافر لديه النزاهة وحسن السمعة .
(د) أن يكون متمتعًا بحقوقه المدنية كاملة .
ثانياً - بالنسبة للأشخاص الاعتباريين
(أ) وضوح هيكل الملكية بما يكفل التعرف على المستفيد النهائي والتأكد من مشروعية مصدر الأموال لطالب التأسيس وأطرافه المرتبطة .
(ب) توافر الملاءة المالية اللازمة لدى طالب التأسيس لدعم أعمال الشركة أو لزيادة رأس مالها إذا دعت الحاجة لذلك .
(ج) إذا كان الطالب شركة أو مؤسسة مالية أجنبية خاضعة لإشراف ورقابة جهة أجنبية مناظرة مختصة في الدولة التي يقع فيها مقرها الرئيسي أن توافق تلك السلطة لها على العمل في جمهورية مصر العربية وأن تطبق مبدأ الرقابة المجمعة .$b1_0$
  FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-11-13', 'active' FROM ins1_0;

WITH ins2_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 2, 0, $h2$القواعد والمعايير المنظمة لمزاولة نشاط إدارة برامج الرعاية الصحية - الفصل الأول - تأسيس وترخيص والقيد بسجل شركات إدارة برامج الرعاية الصحية$h2$, $t2_0$المادة 2 - إجراءات تأسيس الشركة$t2_0$, $b2_0$يقدم طلب الموافقة على تأسيس شركة إدارة برامج الرعاية الصحية إلى الهيئة وفقًا للنموذج المعد منها لهذا الغرض مرفقًا به المستندات الآتية :
1- بيان بأسماء المساهمين وحصة كل منهم وجنسياتهم وخبراتهم السابقة .
2- بيان نسبة ملكية أي من المساهمين في أي من الجهات التي تقدم خدمات الرعاية الطبية التشخيصية أو العلاجية أو التأهيلية .
3- دراسة الجدوى الفنية والاقتصادية للشركة وفقًا للنموذج المعد من الهيئة لهذا الغرض ، على أن تتضمن بحد أدنى ما يلي :
(أ) الجدوى الفنية والاقتصادية لإنشاء الشركة ورؤيتها وآليات استخدام التكنولوجيا في العمليات التشغيلية للشركة ، وخطة عمل فنية خاصة بأعمال التشغيل والمراجعة .
(ب) الهدف والاستراتيجية والسياسة المزمع اتباعها في تصريف شئون الشركة .
(ج) خطة عمل مالية خلال الخمس سنوات الأولى من نشاط الشركة ، على أن تعد التقديرات المالية فيها لكافة بنود القوائم المالية التقديرية وفقًا لمعايير المحاسبة المصرية المرتبطة بالنشاط مع تحديد الأسس الفنية التي بنيت عليها .
(د) أوجه الرقابة الداخلية والحوكمة .
(ه) خطط التدريب والتطوير للعاملين بالشركة .
4- تعهد بالالتزام بتوافر التجهيزات والبنية التكنولوجية وأنظمة المعلومات ووسائل الحماية والتأمين اللازمة لمباشرة النشاط بما يكفل إمكانية الربط الالكتروني مع الهيئة والحفاظ على سرية بيانات وخصوصية معلومات العملاء ، على أن يكون ذلك متوافرًا عند الحصول على الترخيص .
5- إقرار من مراقب حسابات الشركة المقيد لدى الهيئة بقبول التعيين .
6- بيان بالهيكل التنظيمي للشركة .
7- مشروع النظام الأساسي للشركة .
8- صورة بطاقة الرقم القومى للمساهمين من الأشخاص الطبيعيين المصريين وصورة جواز السفر للأجانب ، ومستخرج حديث من السجل التجاري إذا كان المساهم شركة وسند الإنشاء إذا كان شخصًا اعتباريًا من غير الشركات.
9- شهادة تثبت عدم التباس اسم الشركة مع غيرها من الشركات .
10- شهادة تفيد إيداع رأس مال الشركة لدى أحد البنوك المسجلة لدى البنك المركزي المصري .
11- المستند الدال على سداد مقابل فحص طلب تأسيس الشركة وفقًا لقرار مجلس إدارة الهيئة الصادر في هذا الشأن .
12- أي بيانات أو مستندات أخرى ترى الهيئة ضرورة تقديمها للبت في طلب التأسيس .$b2_0$
  FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-11-13', 'active' FROM ins2_0;

WITH ins3_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 3, 0, $h3$القواعد والمعايير المنظمة لمزاولة نشاط إدارة برامج الرعاية الصحية - الفصل الأول - تأسيس وترخيص والقيد بسجل شركات إدارة برامج الرعاية الصحية$h3$, $t3_0$المادة 3 - البت في طلب التأسيس$t3_0$, $b3_0$تسجل الهيئة طلبات التأسيس حسب تاريخ ورودها ، ويخصص لكل طلب ملف خاص (ورقي أو إلكتروني) يحتوي على كافة المستندات والإجراءات ذات الصلة .
وتشكل بقرار من رئيس الهيئة لجنة تضم عناصر فنية وقانونية ومالية لدراسة طلبات التأسيس ، وتقوم تلك اللجنة برفع نتيجة تلك الدراسة إلى رئيس الهيئة أو من يفوضه للنظر فى الموافقة على التأسيس خلال شهر من استيفاء المستندات ، ويتم إخطار وكيل المؤسسين بالقرار خلال أسبوع من تاريخ صدوره .
وللهيئة أن ترفض طلب التأسيس بناءً على دراستها في ضوء الآتي :
1- مدى حاجة السوق إلى شركة جديدة .
2- مدى مساهمة الشركة في تلبية احتياجات السوق ، وعلى الأخص من خلال استخدام وسائل تكنولوجية غير تقليدية أو التوسع في مناطق جديدة .
3- هيكل الملكية لمؤسسي الشركة وخبراتهم وملاءتهم المالية وفقًا للضوابط والمعايير الصادرة عن مجلس إدارة الهيئة .
4- عدم اقتصار غرض الشركة على مزاولة نشاط إدارة برامج الرعاية الصحية .
5- عدم نص النظام الأساسي للشركة على وجوب استخدام أسلوب التصويت التراكمي في انتخاب أعضاء مجلس الإدارة .$b3_0$
  FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-11-13', 'active' FROM ins3_0;

WITH ins4_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 4, 0, $h4$القواعد والمعايير المنظمة لمزاولة نشاط إدارة برامج الرعاية الصحية - الفصل الأول - تأسيس وترخيص والقيد بسجل شركات إدارة برامج الرعاية الصحية$h4$, $t4_0$المادة 4 - إجراءات الحصول على الترخيص$t4_0$, $b4_0$يقدم طلب الترخيص بمزاولة النشاط والقيد لدى الهيئة بسجل شركات إدارة برامج الرعاية الصحية على النموذج المعد منها لهذا الغرض خلال ثلاثة أشهر على الأكثر من تاريخ القيد في السجل التجاري مرفقًا به المستندات الآتية :
1- ثلاث نسخ من العقد الابتدائي للشركة وكذا من النظام الأساسي لها .
2- صورة من البطاقة الضريبية للشركة .
3- أصل مستخرج السجل التجاري للشركة .
4- صورة سند حيازة مقر الشركة .
5- شهادة من إحدى شركات الإيداع والقيد المركزي المرخص لها تفيد إيداع الأوراق المالية للشركة لديها .
6- بيان بتشكيل مجلس الإدارة والمسئولين التنفيذيين بالشركة وفقًا للضوابط المنصوص عليها بهذا القرار ، متضمنًا البيانات الأساسية لهم وعلى الأخص : الاسم والعنوان ، والمؤهل والخبرة ، وصورة من بطاقة الرقم القومي للمصريين ، وصورة من جواز السفر للأجانب .
7- بيان مدى وجود صلة قرابة حتى الدرجة الثانية بين أعضاء مجلس الإدارة أو مع أي من المساهمين أو القائمين على الإدارة التنفيذية للشركة .
8- الإفصاح عن أي حالات محتملة للتعارض في المصالح .
9- سداد رسم تسجيل الشركة .
10- إقرار صادر عن الممثل القانوني للشركة بعدم وجود أي تعديلات على المستندات أو البيانات المقدمة ضمن طلب تأسيس الشركة .
11- أي بيانات أو مستندات أخرى ترى الهيئة ضرورة تقديمها للبت في طلب الترخيص .$b4_0$
  FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision'
