WITH ins5_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 5, 0, $h5$القواعد والمعايير المنظمة لمزاولة نشاط إدارة برامج الرعاية الصحية - الفصل الأول - تأسيس وترخيص والقيد بسجل شركات إدارة برامج الرعاية الصحية$h5$, $t5_0$المادة 5 - البت في طلب الترخيص$t5_0$, $b5_0$تصدر الهيئة قرارها بالبت في طلب الترخيص خلال ثلاثين يومًا على الأكثر من تاريخ تقديم الأوراق مستوفاة إليها.
ويجوز للهيئة قبل إصدار قرار منح الترخيص إجراء الفحص الميداني للتأكد من توافر البنية الإدارية والمعلوماتية والهياكل التنظيمية ، وفي حال عدم استيفاء أي من المتطلبات المشار إليها ، تخطر الهيئة الشركة بما يتوجب عليها استكماله.
وفي حالة رفض طلب الترخيص يجب أن يكون القرار مسببًا.
وفي حال عدم رد الهيئة خلال المدة المشار إليها بالفقرة الأولى من هذه المادة ، اعتبر ذلك بمثابة رفض للطلب.
ولا يجوز للشركة مزاولة نشاطها إلا بعد تمام القيد في سجلات الهيئة ، ويصدر بتسجيل الشركة قرارًا من رئيس الهيئة وينشر قرار التسجيل على الموقع الالكتروني للشركة وكذا الموقع الإلكتروني الذي تخصصه الهيئة لهذا الغرض.
وتلتزم الشركة بالبدء فى مزاولة النشاط خلال ستة أشهر على الأكثر من تاريخ الحصول على الترخيص ، ويجوز بموافقة الهيئة مدها لمدة ستة أشهر أخرى ، وذلك في ضوء المبررات التي تقدمها الشركة وتقبلها الهيئة.
ويتعين على الشركة إخطار الهيئة بأي تعديلات أو تغييرات تطرأ على بيانات طلب التأسيس أو الترخيص بمزاولة النشاط أو المستندات المرفقة به ، ويرفق بالإخطار بيان بتلك التعديلات أو التغييرات ومبرراتها خلال ثلاثين يومًا من تاريخ التعديل على أن يرفق بالإخطار المشار إليه المستندات الخاصة بالتعديل ، ولا يجوز أن يعمل بهذه التعديلات أو التغييرات إلا بعد اعتمادها من الهيئة.$b5_0$
  FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-11-13', 'active' FROM ins5_0;

WITH ins6_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 6, 0, $h6$القواعد والمعايير المنظمة لمزاولة نشاط إدارة برامج الرعاية الصحية - الفصل الأول - تأسيس وترخيص والقيد بسجل شركات إدارة برامج الرعاية الصحية$h6$, $t6_0$المادة 6 - شركات إدارة برامج الرعاية الصحية ذاتية التمويل$t6_0$, $b6_0$يجب على شركات إدارة برامج الرعاية الصحية الراغبة في إدارة برامج الرعاية الصحية ذاتية التمويل لصالح المؤسسات أو الهيئات أو أصحاب الأعمال تقديم طلب للهيئة بذلك ، مع الالتزام بما يلي :
1- الحصول على موافقة الهيئة المسبقة للقيام بمهام إدارة برامج الرعاية الصحية ذاتية التمويل .
2- إخطار الهيئة بنموذج عقود إدارة برامج الرعاية الصحية ذاتية التمويل وأي تعديل يطرأ عليها ولا يجوز العمل بها إلا بعد الحصول على موافقة الهيئة المسبقة بشأنها .
3- تقديم وثيقة تأمين مسئولية مدنية لتعويض الأضرار الناتجة عن مزاولة النشاط ، وذلك بحدود مسئولية قدرها 5 ملايين جنيه وتجدد سنويًا بحدود مسئولية قدرها (25%) من متوسط حجم أعمالها عن العام السابق وبحد أدنى مبلغ 5 ملايين جنيه .
4- تقديم أي بيانات أو مستندات ترى الهيئة ضرورة تقديمها للبت في الطلب .$b6_0$
  FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-11-13', 'active' FROM ins6_0;

WITH ins7_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 7, 0, $h7$القواعد والمعايير المنظمة لمزاولة نشاط إدارة برامج الرعاية الصحية - الفصل الثاني - مجلس إدارة والهيكل التنظيمى لشركات إدارة برامج الرعاية الصحية$h7$, $t7_0$المادة 7 - الشروط الواجب توافرها في أعضاء مجالس إدارة شركات إدارة برامج الرعاية الصحية$t7_0$, $b7_0$يجب أن يتوافر في عضو مجلس إدارة شركة إدارة برامج الرعاية الصحية الشروط الآتية :
1- أن يكون محمود السيرة ، حسن السمعة .
2- ألا يقوم به عارض من عوارض الأهلية .
3- أن يكون متمتعًا بحقوقه المدنية كاملة .
4- أن يكون حاصلاً على مؤهل عال مناسب من إحدى الجامعات المصرية ، أو الأجنبية شريطة معادلته في مصر أو موافقة الهيئة عليه .
5- ألا يكون قد سبق الحكم عليه بحكم بعقوبة جناية ، أو بعقوبة جنحة في جريمة ماسة بالشرف أو الأمانة أو في إحدى الجرائم المنصوص عليها في قوانين الشركات أو القوانين المنظمة للأنشطة المالية غير المصرفية أو قانون مكافحة غسل الأموال ، أو حكم بإشهار إفلاسه ، وذلك خلال الخمس سنوات السابقة على تاريخ تقديم طلب الترشح ما لم يكن قد رد إليه اعتباره .
6- ألا يكون قد صدر ضده أو ضد إحدى الشركات العاملة في مجال الأنشطة المالية غير المصرفية التي كان يشغل رئاسة أو عضوية مجلس إدارتها أو يعمل لديها ، ثمة تدابير إدارية نتيجة مخالفات جسيمة خلال الثلاث سنوات السابقة على شغله لعضوية مجلس الإدارة وكان ذلك بسبب إخلاله بواجباته ومسئولياته .
7- ألا يكون قد سبق فصله عن العمل أو شطبه من سجل إحدى المهن لأمور ماسة بالشرف أو الأمانة ، ما لم يمض على ذلك ثلاث سنوات .
8- أن يتمتع بالاستقلالية اللازمة لأداء مهامه وواجباته ، وألا يكون لديه مصالح تتعارض مع واجبات رئاسة أو عضوية مجلس إدارة الشركة أو تؤثر على قدرته في القيام بذلك .
9- الإلمام بالتشريعات الصادرة في مجال التأمين وإدارة برامج الرعاية الصحية ، وأن يتوافر لديه شروط الخبرة الآتية :
(أ) بالنسبة للعضو المنتدب / الرئيس التنفيذي : خمس سنوات على الأقل في مجال التأمين أو إعادة التأمين أو الرعاية الصحية .
(ب) بالنسبة لباقي أعضاء المجلس : يجب أن يتوافر خبرة مجال التأمين أو إعادة التأمين أو الخبرة الاكتوارية أو الرعاية الصحية أو في إحدى المجالات القانونية أو المحاسبية أو المالية أو الاستثمارية أو إدارة الأعمال أو تكنولوجيا المعلومات والتحول الرقمي المتعلقة بمجال عمل الشركة .
10- اجتياز العضو المنتدب / الرئيس التنفيذي للمقابلة الشخصية التي تعقدها الهيئة في هذا الشأن . وللهيئة إجراء مقابلة شخصية مع باقى المرشحين لعضوية مجلس إدارة الشركة ، ويجوز أن تتم هذه المقابلات بإحدى وسائل الاتصالات الحديثة .
11- أن يكون للممثل القانوني للشركة توقيع إلكتروني .
ويشترط لاستمرار العضوية بمجلس إدارة الشركة استمرار توافر البنود (1 ، 2 ، 3 ، 5 ، 8) من هذه المادة ، وفي حال فقد العضو أي منها تزول عضويته بمجلس إدارة الشركة ، ويتعين على مجلس إدارة الشركة اتخاذ الإجراءات اللازمة حيال ذلك .
وفي جميع الأحوال ، تلتزم شركات إدارة برامج الرعاية الصحية عند تشكيل مجلس إدارتها بالضوابط الآتية :
1- أن يكون أغلبية أعضاء مجلس إدارة الشركة من غير التنفيذيين .
2- مراعاة التنوع في مجالات الخبرة في تشكيل مجلس إدارة الشركة .
3- أن يتضمن تشكيل مجلس الإدارة عضو واحد على الأقل - بخلاف العضو المنتدب - لديه خبرة في مجال تكنولوجيا المعلومات والتحول الرقمي المتعلقة بمجال عمل الشركة .
4- أن يتضمن تشكيل المجلس تمثيلاً نسائيًا وفقًا للقرار الصادر عن الهيئة في هذا الشأن .
5- عدم الجمع بين منصب رئيس مجلس الإدارة والعضو المنتدب / الرئيس التنفيذي .
6- إخطار الهيئة عند أي تغيير يطرأ على تشكيل المجلس خلال أسبوع على الأكثر من تاريخ التغيير مرفقًا به كافة البيانات والمستندات المتعلقة بذلك .$b7_0$
  FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-11-13', 'active' FROM ins7_0;

WITH ins8_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 8, 0, $h8$القواعد والمعايير المنظمة لمزاولة نشاط إدارة برامج الرعاية الصحية - الفصل الثاني - مجلس إدارة والهيكل التنظيمى لشركات إدارة برامج الرعاية الصحية$h8$, $t8_0$المادة 8 - الهيكل التنظيمي والشروط والمعايير الواجب توافرها في المسئولين التنفيذيين بشركات إدارة برامج الرعاية الصحية$t8_0$, $b8_0$يجب أن يتضمن الهيكل التنظيمي لشركات إدارة برامج الرعاية الصحية مسئولاً رئيسيًا عن كل من الإدارات الآتية : المطالبات ، والموافقات الطبية ، والمالية ، وتكنولوجيا المعلومات والتحول الرقمي ، والمراجعة داخلية ، والالتزام ، وشكاوى العملاء ، ومكافحة غسل الأموال وتمويل الإرهاب .
ومع عدم الإخلال بقرار مجلس إدارة الهيئة رقم 161 لسنة 2024 المشار إليه ، لا يجوز للشركة دمج أي من تلك الإدارات عدا مسئول مكافحة غسل الأموال وتمويل الإرهاب فيجوز أن يجمع المسئول عن الالتزام بين مهامه والمهام المقررة لمسئول مكافحة غسل الأموال وتمويل الإرهاب .
وتلتزم الشركة بإخطار الهيئة بأسماء المسئولين التنفيذيين لديها وأي تغير يطرأ عليه خلال أسبوع على الأكثر من حدوثه على أن يرفق بذلك كافة البيانات والمستندات المتعلقة بذلك .
ويشترط أن يتوافر في المسئولين التنفيذيين المشار إليهم ما يلي :
1- الشروط المنصوص عليها بالبنود من (1 إلى 8) بالمادة السابقة من هذا القرار .
2- ألا تقل مدة خبرتهم عن خمس سنوات في مجال التأمين أو إعادة التأمين أو في أحد المجالات القانونية أو المحاسبية أو التمويلية أو الاستثمارية أو إدارة الأعمال أو تكنولوجيا المعلومات أو الرعاية الصحية وذلك بحسب طبيعة الوظيفة المرشح لها.
3- ألا يكون عاملاً بأي وجه وبأي صفة في شركة أو جهة أخرى أو لدى أي من الجهات التي تقدم خدمات الرعاية الطبية التشخيصية أو العلاجية أو التأهيلية على نحو يخل بمهام وظيفته بالشركة .
ويجوز للهيئة إجراء مقابلة شخصية مع المسئولين التنفيذيين المرشحين لتولي مهام الإدارات المشار إليها .$b8_0$
  FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-11-13', 'active' FROM ins8_0;

WITH ins9_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 9, 0, $h9$القواعد والمعايير المنظمة لمزاولة نشاط إدارة برامج الرعاية الصحية - الفصل الثالث - الالتزامات والمحظورات على شركات إدارة برامج الرعاية الصحية$h9$, $t9_0$المادة 9 - التزامات الشركة$t9_0$, $b9_0$تلتزم جميع الشركات المخاطبة بأحكام هذا القرار بإدارة جميع الأعمال الإدارية المرتبطة بوثائق التأمين الطبي الصادرة عن شركات التأمين ، كطرف ثالث بين شركة التأمين والعميل ، وتلتزم جميع شركات إدارة برامج الرعاية الصحية بما يلي :
1- تحري الدقة والموضوعية والحياد عند تسوية المطالبات ، ومعاملة شركات التأمين ومقدمي خدمات العلاج الطبي المتعاقدين معها دون تمييز أو تحيز .
2- المحافظة على مستوى الخدمات المقدمة للعميل طيلة فترة سريان وثيقة التأمين ، وذلك وفقًا لأحكام العقود المبرمة بينها وبين شركة التأمين .
3- الالتزام بأحكام العقود المبرمة بينها وبين شركة التأمين ، وكذا بينها وبين المتعاقدين على إدارة برامج الرعاية الصحية ذاتية التمويل .
4- الحصول على موافقة الهيئة المسبقة قبل إبرام أي عقد مع شركات بالخارج لتقديم خدمات الرعاية الصحية لصالح أي من شركاتها أو عملائها ، بصورة مؤقتة داخل جمهورية مصر العربية .
5- تحديد وتقييم مستوى المخاطر الذي يمكن للشركة قبوله والتأكد من عدم تجاوز الشركة لهذا الحد من المخاطر.
6- إلزام موظفيها وممثليها عند تعاملهم مع الغير بالتعريف بالشركة وبشركة التأمين المتعاقدة معها وبمقدمي خدمات العلاج الطبى ، وبيان طبيعة الخدمات المرخص لها بتقديمها .
7- وضع نظام رقابة داخلية يتناسب مع حجم أعمالها وطبيعة نشاطها .
8- مراجعة المطالبات الصادرة عن مقدمي خدمات العلاج الطبي قبل إحالتها إلى شركة التأمين .
9- التأكد من أن الخدمات المقدمة للعميل مغطاة ضمن وثيقة التأمين الطبي قبل إحالة المطالبة إلى شركة التأمين .
10- إنهاء الإجراءات التي تتطلب موافقة مسبقة من شركة التأمين ، وذلك خلال المواعيد المتفق عليها بين أطراف التعاقد .
11- موافاة شركة التأمين بالتقارير أو الإحصائيات التي تطلبها بشأن نتائج أعمالها معها ، وذلك وفقًا لما يتم الاتفاق عليه .
12- إطلاع شركة التأمين على نماذج العقود المبرمة مع مقدمي خدمات العلاج الطبي حال طلبها والإفصاح عن أي خصومات بما في ذلك الخصومات المرتبطة بحجم الأعمال .
13- تسديد مبالغ المطالبات إلى مقدمي خدمات العلاج الطبي خلال المدة المتفق عليها في العقد .
14- إخطار شركة التأمين والمتعاقد فورًا عند إبرام أو إنهاء أو وقف أي تعاقد أو إجراء أي تعديلات جوهرية على العقد المبرم مع أي من مقدمي خدمات العلاج الطبي .
15- فصل حساباتها عن حسابات عقود إدارة برامج الرعاية الصحية ذاتية التمويل .
16- إمساك حسابات منفصلة لكل شركة تأمين تتعاقد معها لإدارة برامج الرعاية الصحية.
17- المحافظة على سرية البيانات وخصوصية المعلومات التي تحصل عليها بحكم عملها ويحظر عليها الإفصاح عن أي منها للغير إلا بناءً على موافقة الكتابية المسبقة من ذوي الشأن وفى حدود هذه الموافقة ، أو في الحالات التي يلزم فيها تقديم معلومات محددة للهيئة أو الهيئات القضائية .$b9_0$
  FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-11-13', 'active' FROM ins9_0;

WITH ins10_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 10, 0, $h10$القواعد والمعايير المنظمة لمزاولة نشاط إدارة برامج الرعاية الصحية - الفصل الثالث - الالتزامات والمحظورات على شركات إدارة برامج الرعاية الصحية$h10$, $t10_0$المادة 10 - المحظورات$t10_0$, $b10_0$يحظر على شركات إدارة برامج الرعاية الصحية القيام بأي مما يلي :
1- بيع أو تسويق أو التوسط في إصدار أي وثائق تأمين سواء لحسابها أو لحساب الغير .
2- ممارسة نشاط التأمين أو أي من الأنشطة أو المهن المرتبطة به عدا النشاط المرخص لها بمزاولته ، أو تحديد الأقساط أو الاشتراكات السابقة أو اللاحقة في برامجها تحت أي مسمى أو تحصيلها من العميل .
3- الاحتفاظ بأي مبالغ ناتجة عن تسوية المطالبات بمبالغ أقل مما تم استلامه لحساب تلك المطالبات ، ويتعين عليها إعادة تلك المبالغ لشركة التأمين خلال العشرة أيام الأولى من الشهر التالي لتسوية المطالبات ، ما لم يتم الاتفاق على خلاف ذلك .
4- احتساب أتعاب الإدارة كنسبة من قيمة المطالبات .
5- القيام بأي تصرف من شأنه التأثير على قرار المؤمن له بشأن التعاقد مع شركة تأمين دون غيرها ، أو الاستمرار في التعامل مع إحداها .
6- نشر أي بيان من البيانات إلا إذا كانت مطابقة للبيانات التي تم تقديمها للهيئة ، ويجوز لها نشر مستخرجات من هذه البيانات مطابقة تمامًا لمشتملات البيانات الأصلية المقدمة .
7- قبول أي عمليات من وسطاء التأمين ويقتصر قبول عملياتها على الجهاز التسويقي الملتحق بعلاقة عمل معها .$b10_0$
  FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-11-13', 'active' FROM ins10_0;

WITH ins11_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 11, 0, $h11$القواعد والمعايير المنظمة لمزاولة نشاط إدارة برامج الرعاية الصحية - الفصل الثالث - الالتزامات والمحظورات على شركات إدارة برامج الرعاية الصحية$h11$, $t11_0$المادة 11 - السجلات التي يتعين على الشركة إمساكها$t11_0$, $b11_0$تلتزم الشركات المخاطبة بأحكام هذا القرار بإمساك السجلات الآتية :
1- سجل الوثائق ويتضمن الوثائق وجداول المزايا والمنافع التي تقوم الشركة بإدارتها .
2- سجل العقود المبرمة مع شركات التأمين ومقدمي الخدمات الطبية ، ويتضمن أسماء الشركات وتاريخ بداية ونهاية التعاقد وما يرتبط بهذه العقود من تعديلات تتم عليها .
3- سجل المخالصات التي تم استلامها من مقدم الخدمات الطبية .
4- سجل بالضمانات المقدمة لمقدمي الخدمات الطبية .
5- سجل الشكاوى التي ترد لها من المؤمن عليهم أو المستفيدين أو من مقدمي الخدمات الطبية ، ويتضمن تاريخ تقديم الشكوى ورقم مسلسل قيدها واسم مقدمها ، وبيان موجز بموضوعها وبيان بالمستندات المرفقة بها أو المقدمة تأييدًا لها.
6- سجل الدعاوى القضائية أو التحكيمية المرفوعة ضد الشركة أو التي تكون طرفًا فيها.
7- سجل تفصيلي بأرصدة الحسابات لكل شركة تأمين على حدة موضحًا به المبالغ المستوفاة منها والمديونيات المعلقة بينهما.
8- سجل تفصيلي بالمطالبات التي ترد لها من مقدمي الخدمات الطبية لكل شركة تأمين على حدة ولكل عميل من عملاء البرامج ذاتية التمويل على حدة .
9- سجل تفصيلي بالمطالبات المرفوضة لكل شركة تأمين على حدة ولكل عميل من عملاء البرامج ذاتية التمويل على حدة .
وتلتزم الشركات بالاحتفاظ بالسجلات المشار إليها لمدة لا تقل عن خمس سنوات ، وذلك فيما عدا الحالات التي توجد بشأنها دعاوي قضائية أو تحكيمية ؛ فيجب على الشركة اتخاذ الإجراءات اللازمة للاحتفاظ بالبيانات والمستندات الخاصة بموضوع الدعوى لحين صدور حكم نهائي فيها .
كما يجوز الاحتفاظ بالسجلات المشار إليها بهذه المادة بشكل إلكتروني .$b11_0$
  FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-11-13', 'active' FROM ins11_0;

WITH ins12_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 12, 0, $h12$القواعد والمعايير المنظمة لمزاولة نشاط إدارة برامج الرعاية الصحية - الفصل الثالث - الالتزامات والمحظورات على شركات إدارة برامج الرعاية الصحية$h12$, $t12_0$المادة 12 - التعهيد$t12_0$, $b12_0$تلتزم شركات إدارة برامج الرعاية الصحية عند الاستعانة بإحدى الجهات المتخصصة لإنشاء أو تصميم أو تطوير البرنامج للشركة بغرض تقديم الخدمة بالتحقق من استيفاء الاشتراطات المتطلبة في البرنامج حال توفيره من خلال إحدى هذه الجهات بما في ذلك التزام الشركة بالإشراف على إجراء الاختبارات اللازمة ، وكذا تكون مسئولة عن المخاطر التشغيلية للبرنامج ، كما يجب أن يتوافر لدى الشركة خطة لتوريد وتشغيل البرنامج حال اعتمادها على جهات أخرى لتوفير الخدمة .$b12_0$
  FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
