WITH ins13_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 13, 0, $h13$القواعد والمعايير المنظمة لمزاولة نشاط إدارة برامج الرعاية الصحية - الفصل الرابع - حوكمة شركات إدارة برامج الرعاية الصحية$h13$, $t13_0$المادة 13 - الجمعية العامة للشركة$t13_0$, $b13_0$على شركة إدارة برامج الرعاية الصحية دعوة الجمعية العامة للانعقاد في الزمان والمكان اللذين يعينهما نظام الشركة ويجب أن تعقد الجمعية مرة على الأقل في السنة خلال الثلاثة شهور التالية لنهاية السنة المالية للشركة ، ولمجلس الإدارة أن يقرر دعوة الجمعية العامة كلما دعت الضرورة إلى ذلك .
ويجب على مراقب الحسابات أن يدعو الجمعية العامة للانعقاد في الأحوال التي يتراخى فيها رئيس مجلس الإدارة عن دعوة الجمعية العامة للانعقاد خلال الثلاثة أشهر التالية لنهاية السنة المالية للشركة .
وعلى الشركة أن تخطر الهيئة بموعد ومكان انعقاد الجمعية العامة لها وجدول أعمالها قبل موعد الانعقاد بثلاثين يومًا ، على أن يرفق بالإخطار جميع المستندات التي تقدم للمساهمين .
وتلتزم الشركة بإدراج ما ترى الهيئة عرضه كبند من بنود جدول أعمال الجمعية العامة للشركة ، وعلى رئيس الجمعية تلاوة ملخص لتقرير الهيئة في حالة عدم حضور ممثل عن الهيئة .
