WITH ins22_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 22, 0, $h22$القواعد والمعايير المنظمة لمزاولة نشاط إدارة برامج الرعاية الصحية - الفصل الرابع - حوكمة شركات إدارة برامج الرعاية الصحية$h22$, $t22_0$المادة 22 - اجتماعات مجلس الإدارة$t22_0$, $b22_0$ينعقد مجلس إدارة الشركة بناءً على دعوة من رئيسه أو نائبه ، ويجوز للعضو المنتدب / الرئيس التنفيذي أو ثلث أعضاء المجلس التقدم كتابة لرئيس المجلس بطلب دعوة مجلس الإدارة للانعقاد على أن يتضمن الطلب تحديد موعد ومكان الاجتماع وجدول الأعمال ، وعلى رئيس المجلس الالتزام بدعوة المجلس وذلك قبل ثلاثة أيام عمل على الأقل عن الموعد المحدد للاجتماع ، وفي حال تخلف رئيس المجلس عن دعوة المجلس فلطالبي الاجتماع القيام بدعوة كافة أعضاء مجلس الإدارة مباشرة وإخطار الهيئة بذلك قبل ثلاثة أيام عمل على الأقل من الموعد المحدد للاجتماع وذلك وفقًا للقواعد والإجراءات المعمول بها في هذا الشأن بالشركة .
ويتعين عند توجيه الدعوة لاجتماعات المجلس مراعاة تحديد موعد ومكان الانعقاد بما يتناسب مع ظروف الأعضاء ويتيح الحضور الفعلي ، ودون الإخلال بالنظام الأساسي للشركة.
وعلى مجلس الإدارة الاجتماع كلما دعت الحاجة لذلك ، ويتم الإفصاح في التقرير السنوي للشركة عن عدد اجتماعات مجلس الإدارة المنعقدة وأسماء الأعضاء الذين تغيبوا عن حضور اجتماعات المجلس أو لجانه .
وفي جميع الأحوال ، لا يجوز لأي عضو أن يتغيب عن اجتماعات مجلس إدارة الشركة لأكثر من ثلث عدد جلساته خلال السنة ، وإذا تجاوز تغيب أي عضو ثلث اجتماعات المجلس فيتعين على رئيس المجلس إخطار الجمعية العامة بذلك لاتخاذ ما تراه مناسبًا في شأن استمرار عضويته بالمجلس .
وتتخذ قرارات مجلس الإدارة بأغلبية أصوات الأعضاء الحاضرين ، وفي الحالات العاجلة التي لا تحتمل التأجيل يجوز اتخاذ القرارات بطريق التمرير شريطة قيام أمانة سر المجلس بإرفاق كافة المستندات والبيانات المتعلقة بالموضوعات المعروضة بالتمرير ، وموافقة جميع أعضاء مجلس الإدارة على القرارات كتابة ، على أن يتم إثبات تلك القرارات في محضر أول اجتماع لاحق لمجلس الإدارة .
ولمجلس الإدارة الاستعانة بمن يراه ضروريًا لحضور اجتماعاته دون أن يكون له صوت معدود عند التصويت.
ويجوز لمجلس الإدارة عقد اجتماعاته باستخدام وسائل الاتصال الحديثة أو أي وسيلة إلكترونية أخرى شريطة أن ينص النظام الأساسي للشركة على ذلك ، وألا يزيد عدد الاجتماعات المنعقدة بتلك الوسائل عن ثلث عدد اجتماعات المجلس خلال السنة وألا يقل عدد الحضور الفعلي عن نصف أعضاء المجلس ، على أن يكون من بينهم العضو المنتدب / الرئيس التنفيذي ، ويحدد مجلس إدارة الشركة ضوابط وإجراءات عقد الاجتماعات باستخدام تلك الوسائل.
وتعتبر مشاركة عضو مجلس الإدارة عبر هذه الوسائل مشاركة فعلية في الاجتماع ، ويحسب ضمن النصاب القانوني لصحة الانعقاد والتصويت .
ويجوز لمجلس الإدارة تشكيل لجان عن مجلس الإدارة تكلف بموضوعات معينة بحسب حاجة وطبيعة عمل الشركة ، وعلى مجلس الإدارة تحديد مدة عمل وصلاحيات هذه اللجان وتشكيلها ومعاملتها المالية وتنظيم كيفية عملها .$b22_0$
  FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-11-13', 'active' FROM ins22_0;

WITH ins23_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 23, 0, $h23$القواعد والمعايير المنظمة لمزاولة نشاط إدارة برامج الرعاية الصحية - الفصل الرابع - حوكمة شركات إدارة برامج الرعاية الصحية$h23$, $t23_0$المادة 23 - تسجيل وحفظ محاضر اجتماعات مجلس الإدارة$t23_0$, $b23_0$تلتزم الشركات المخاطبة بأحكام هذا القرار بتسجيل مناقشات اجتماعات مجلس الإدارة وتوقيعها من قبل رئيس المجلس وأمين السر وحفظها في سجل دائم للأعمال والقرارات المتخذة من المجلس ، مع مراعاة الدقة والوضوح في إعدادها.
ويجب على الشركة حفظ محاضر اجتماعات مجلس الإدارة من خلال سجل إلكتروني دائم وفقًا للضوابط المنصوص عليها في المادة (15) من هذا القرار ، وبما يضمن سلامة الحفظ والتوثيق وعدم جواز التعديل أو الحذف ، مع وجود نسخة احتياطية منها.
ويجب أن تتضمن محاضر اجتماعات مجلس الإدارة أسماء الأعضاء الحاضرين والغائبين والموضوعات التي تمت مناقشتها بشكل تفصيلي ، والمداولات الرئيسية التي دارت بشأنها ، ونتائج التصويت على كل موضوع مع بيان أسماء الموافقين والمعترضين والممتنعين عن التصويت وأسباب الاعتراض أو الامتناع إن وجدت ، وكذا القرارات التي تم اتخاذها وأي تحفظات بشأنها ، على أن يرفق بالمحضر كافة الوثائق والسجلات والمستندات التي تم الاطلاع عليها خلال الاجتماع أو تمت الإشارة إليها ضمن محضر الاجتماع .$b23_0$
  FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-11-13', 'active' FROM ins23_0;

WITH ins24_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 24, 0, $h24$القواعد والمعايير المنظمة لمزاولة نشاط إدارة برامج الرعاية الصحية - الفصل الرابع - حوكمة شركات إدارة برامج الرعاية الصحية$h24$, $t24_0$المادة 24 - سياسة منع تعارض المصالح$t24_0$, $b24_0$تلتزم الشركات المخاطبة بأحكام هذا القرار بإعداد سياسة تهدف إلى منع تعارض المصالح الأعضاء مجلس الإدارة والعاملين بها وذلك تعزيزًا لمبادئ النزاهة والشفافية وتطبيقًا لمبدأ المساءلة والمحاسبة عن أي أعمال أو ممارسات قد تؤدي إلى تعارض المصالح .
ويجب أن تتضمن سياسة التناسب والملاءمة الخاصة بشغل الوظائف التنفيذية بالشركة على قواعد وضوابط لتجنب تعارض المصالح ، بما في ذلك وضع آليات الإفصاح عن تلك الحالات أو الشبهة بها والإجراءات الواجب اتباعها لمواجهتها .$b24_0$
  FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-11-13', 'active' FROM ins24_0;

DO $verify163$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 229 AND law_year = 2025 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[163] القرار 229/2025 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 28 THEN RAISE EXCEPTION '[163] عدد المواد % بدل 28', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2025-11-13';
  IF v_v <> 28 THEN RAISE EXCEPTION '[163] عدد النسخ % بدل 28', v_v; END IF;
  SELECT count(*) INTO v_bad FROM articles WHERE law_id = v_law_id AND (body ~ '[٠-٩۰-۹]' OR body ~ '[ٌ-ْ]' OR body LIKE '%' || chr(65533) || '%' OR body LIKE '%ـ%' OR body LIKE '%ة ال يع%' OR body LIKE '%ه ال يع%' OR body LIKE '%تد بها%' OR body LIKE '% تروني%' OR body LIKE '%ل تداول%' OR body LIKE '%لك تروني%' OR body LIKE '%الوقائع المصریة%' OR body LIKE '%العدد 254%' OR body LIKE '%سنوي ا%' OR body LIKE '%دائم ا%' OR body LIKE '%فني ا%' OR body LIKE '%مسبق ا%' OR body LIKE '%حالي ا%' OR body LIKE '%الفصل الأول%' OR body LIKE '%الفصل الثاني%' OR body LIKE '%الفصل الثالث%' OR body LIKE '%الفصل الرابع%' OR body LIKE '%ھ%' OR body LIKE '%ی%');
  IF v_bad > 0 THEN RAISE EXCEPTION '[163] % مادة بها تلف أو بقايا OCR أو ترويسة', v_bad; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND body LIKE 'بعد الاطلاع على القانون رقم 10 لسنة 2009 بتنظ%' AND body LIKE '%ته المنعقدة بتاريخ 2025/9/24 ؛' AND body LIKE '%رقم 10 لسنة 2009%' AND body LIKE '%رقم 155 لسنة 2024%' AND body LIKE '%رقم 244 لسنة 2023%' AND body LIKE '%رقم 161 لسنة 2024 بشأن%' AND body LIKE '%رقم 177 لسنة 2024%' AND body LIKE '%رقم 196 لسنة 2024%' AND body LIKE '%رقم 90 لسنة 2025%' AND body LIKE '%بتاريخ 2025/9/24 ؛%') THEN RAISE EXCEPTION '[163] ديباجة غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = -1 AND body LIKE 'تسري القواعد والمعايير المرفقة بهذا القرار في%' AND body LIKE '%تمرار الترخيص بمزاولة النشاط .' AND body LIKE '%إلا بعد الحصول على ترخيص بذلك من الهيئة والقيد لديها في السجل المعد لذلك .%' AND body LIKE '%شرطًا لاستمرار الترخيص بمزاولة النشاط .%') THEN RAISE EXCEPTION '[163] مادة الإصدار 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = -1 AND body LIKE 'على شركات إدارة برامج الرعاية الصحية القائمة%' AND body LIKE '%ة مدة توفيق الأوضاع المذكورة .' AND body LIKE '%وفقًا لأحكام قرار مجلس إدارة الهيئة رقم 90 لسنة 2025 المشار إليه%' AND body LIKE '%خلال مدة أقصاها 2026/7/10 ، ويجوز مد%' AND body LIKE '%في نهاية مدة توفيق الأوضاع المذكورة .%') THEN RAISE EXCEPTION '[163] مادة الإصدار 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 3 AND article_suffix_order = -1 AND body LIKE 'ينشر هذا القرار في الوقائع المصرية وعلى الموق%' AND body LIKE '%د/ محمد فريد صالح' AND body LIKE '%ويعمل به من اليوم التالي لتاريخ نشره بالوقائع المصرية .%' AND body LIKE '%د/ محمد فريد صالح') THEN RAISE EXCEPTION '[163] مادة الإصدار 3 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0 AND body LIKE 'يشترط لتأسيس وترخيص شركات إدارة برامج الرعاية%' AND body LIKE '%أن تطبق مبدأ الرقابة المجمعة .' AND body LIKE '%رقم 196 لسنة 2024 المشار إليه .%' AND body LIKE '%السنوات الخمس السابقة%' AND body LIKE '%(ج) أن يتوافر لديه النزاهة وحسن السمعة .%' AND body LIKE '%2- ألا يقل رأس مالها%') THEN RAISE EXCEPTION '[163] المادة 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = 0 AND body LIKE 'يقدم طلب الموافقة على تأسيس شركة إدارة برامج%' AND body LIKE '%تقديمها للبت في طلب التأسيس .' AND body LIKE '%(ه) خطط التدريب والتطوير%' AND body LIKE '%12- أي بيانات%' AND body LIKE '%الخمس سنوات الأولى%' AND body LIKE '%10- شهادة تفيد%') THEN RAISE EXCEPTION '[163] المادة 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 3 AND article_suffix_order = 0 AND body LIKE 'تسجل الهيئة طلبات التأسيس حسب تاريخ ورودها ،%' AND body LIKE '%في انتخاب أعضاء مجلس الإدارة .' AND body LIKE '%خلال شهر من استيفاء المستندات%' AND body LIKE '%خلال أسبوع من تاريخ صدوره%' AND body LIKE '%5- عدم نص%') THEN RAISE EXCEPTION '[163] المادة 3 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 4 AND article_suffix_order = 0 AND body LIKE 'يقدم طلب الترخيص بمزاولة النشاط والقيد لدى ال%' AND body LIKE '%تقديمها للبت في طلب الترخيص .' AND body LIKE '%خلال ثلاثة أشهر على الأكثر%' AND body LIKE '%11- أي بيانات%' AND body LIKE '%10- إقرار صادر%') THEN RAISE EXCEPTION '[163] المادة 4 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 5 AND article_suffix_order = 0 AND body LIKE 'تصدر الهيئة قرارها بالبت في طلب الترخيص خلال%' AND body LIKE '%ات إلا بعد اعتمادها من الهيئة.' AND body LIKE '%خلال ثلاثين يومًا على الأكثر%' AND body LIKE '%ستة أشهر على الأكثر%' AND body LIKE '%ستة أشهر أخرى%' AND body LIKE '%خلال ثلاثين يومًا من تاريخ التعديل%') THEN RAISE EXCEPTION '[163] المادة 5 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 6 AND article_suffix_order = 0 AND body LIKE 'يجب على شركات إدارة برامج الرعاية الصحية الرا%' AND body LIKE '%ضرورة تقديمها للبت في الطلب .' AND body LIKE '%قدرها (25_) من متوسط%' AND body LIKE '%قدرها 5 ملايين جنيه وتجدد%' AND body LIKE '%مبلغ 5 ملايين جنيه .%' AND body LIKE '%4- تقديم أي بيانات%') THEN RAISE EXCEPTION '[163] المادة 6 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 7 AND article_suffix_order = 0 AND body LIKE 'يجب أن يتوافر في عضو مجلس إدارة شركة إدارة بر%' AND body LIKE '%نات والمستندات المتعلقة بذلك .' AND body LIKE '%البنود (1 ، 2 ، 3 ، 5 ، 8) من هذه المادة%' AND body LIKE '%خلال الخمس سنوات السابقة%' AND body LIKE '%خلال الثلاث سنوات السابقة%' AND body LIKE '%ثلاث سنوات .%' AND body LIKE '%المنتدب / الرئيس التنفيذي : خمس سنوات%' AND body LIKE '%11- أن يكون للممثل%' AND body LIKE '%6- إخطار الهيئة%' AND body LIKE '%خلال أسبوع على الأكثر%' AND body LIKE '%10- اجتياز العضو المنتدب / الرئيس التنفيذي%') THEN RAISE EXCEPTION '[163] المادة 7 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 8 AND article_suffix_order = 0 AND body LIKE 'يجب أن يتضمن الهيكل التنظيمي لشركات إدارة برا%' AND body LIKE '%ي مهام الإدارات المشار إليها .' AND body LIKE '%بالبنود من (1 إلى 8) بالمادة السابقة%' AND body LIKE '%رقم 161 لسنة 2024 المشار إليه%' AND body LIKE '%خمس سنوات في مجال%') THEN RAISE EXCEPTION '[163] المادة 8 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 9 AND article_suffix_order = 0 AND body LIKE 'تلتزم جميع الشركات المخاطبة بأحكام هذا القرار%' AND body LIKE '%ة للهيئة أو الهيئات القضائية .' AND body LIKE '%17- المحافظة على سرية%' AND body LIKE '%10- إنهاء%' AND body LIKE '%14- إخطار%' AND body LIKE '%بناءً على موافقة الكتابية%' AND body LIKE '%خلال المواعيد المتفق عليها%') THEN RAISE EXCEPTION '[163] المادة 9 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 10 AND article_suffix_order = 0 AND body LIKE 'يحظر على شركات إدارة برامج الرعاية الصحية الق%' AND body LIKE '%ويقي الملتحق بعلاقة عمل معها .' AND body LIKE '%خلال العشرة أيام الأولى%' AND body LIKE '%7- قبول أي%') THEN RAISE EXCEPTION '[163] المادة 10 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 11 AND article_suffix_order = 0 AND body LIKE 'تلتزم الشركات المخاطبة بأحكام هذا القرار بإمس%' AND body LIKE '%ها بهذه المادة بشكل إلكتروني .' AND body LIKE '%9- سجل تفصيلي بالمطالبات المرفوضة%' AND body LIKE '%لا تقل عن خمس سنوات ،%') THEN RAISE EXCEPTION '[163] المادة 11 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 12 AND article_suffix_order = 0 AND body LIKE 'تلتزم شركات إدارة برامج الرعاية الصحية عند ال%' AND body LIKE '%على جهات أخرى لتوفير الخدمة .' AND body LIKE '%خطة لتوريد وتشغيل البرنامج%') THEN RAISE EXCEPTION '[163] المادة 12 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 13 AND article_suffix_order = 0 AND body LIKE 'على شركة إدارة برامج الرعاية الصحية دعوة الجم%' AND body LIKE '%انعقاد الجمعية للتصديق عليه .' AND body LIKE '%قبل موعد الانعقاد بثلاثين يومًا ،%' AND body LIKE '%الثلاثة شهور التالية%' AND body LIKE '%الثلاثة أشهر التالية%' AND body LIKE '%موعد أقصاه ثلاثين يومًا من تاريخ انعقاد%') THEN RAISE EXCEPTION '[163] المادة 13 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 14 AND article_suffix_order = 0 AND body LIKE 'تختص الجمعية العامة بالنظر في جدول الأعمال ال%' AND body LIKE '%تشريعات الصادرة في هذا الشأن .' AND body LIKE '%11- النظر في أي موضوعات%' AND body LIKE '%10- النظر في عقود%') THEN RAISE EXCEPTION '[163] المادة 14 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 15 AND article_suffix_order = 0 AND body LIKE 'يجوز للشركة تسجيل مناقشات اجتماعات الجمعية ال%' AND body LIKE '%د محضر اجتماع الجمعية العامة .' AND body LIKE '%رقم 15 لسنة 2004%' AND body LIKE '%2- أن يتوافر%') THEN RAISE EXCEPTION '[163] المادة 15 غير سليم'; END IF;
