  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 20 AND article_suffix_order = 0 AND body LIKE 'تلتزم مجالس إدارة الشركات المخاطبة بأحكام هذا%' AND body LIKE '%يا والمتعلقة بمهامهم الوظيفية.' AND body LIKE '%18- بيان التدابير%' AND body LIKE '%10- تقرير عن نتائج%' AND body LIKE '%12- تشكيل مجلس%') THEN RAISE EXCEPTION '[163] المادة 20 غير سليم'; END IF;
