  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 22 AND article_suffix_order = 0 AND body LIKE 'ينعقد مجلس إدارة الشركة بناءً على دعوة من رئي%' AND body LIKE '%ا المالية وتنظيم كيفية عملها .' AND body LIKE '%ثلث أعضاء المجلس%' AND body LIKE '%ثلاثة أيام عمل على الأقل عن%' AND body LIKE '%ثلاثة أيام عمل على الأقل من%' AND body LIKE '%ثلث عدد جلساته%' AND body LIKE '%ثلث عدد اجتماعات المجلس خلال السنة وألا يقل%' AND body LIKE '%نصف أعضاء المجلس%' AND body LIKE '%المنتدب / الرئيس التنفيذي ، ويحدد%') THEN RAISE EXCEPTION '[163] المادة 22 غير سليم'; END IF;
